<script setup>
/**
 * EmptyState.vue - 空状态展示组件
 * 
 * Props:
 * - icon: string - 表情符号/图标 (默认: '📭')
 * - title: string - 标题文字 (默认: '暂无数据')
 * - description: string - 描述文字
 * - actionText: string - 操作按钮文字 (可选)
 * 
 * Emits:
 * - action: 点击操作按钮时触发
 */

defineProps({
  icon: {
    type: String,
    default: '📭'
  },
  title: {
    type: String,
    default: '暂无数据'
  },
  description: {
    type: String,
    default: '这里还没有内容，去看看其他页面吧'
  },
  actionText: {
    type: String,
    default: ''
  }
})

const emit = defineEmits(['action'])

// 处理操作按钮点击
const handleAction = () => {
  emit('action')
}
</script>

<template>
  <div class="empty-state">
    <!-- 图标 -->
    <div class="empty-icon">{{ icon }}</div>

    <!-- 标题 -->
    <h3 class="empty-title">{{ title }}</h3>

    <!-- 描述 -->
    <p v-if="description" class="empty-description">{{ description }}</p>

    <!-- 操作按钮 -->
    <button
      v-if="actionText"
      class="empty-action-btn"
      @click="handleAction"
    >
      {{ actionText }}
    </button>
  </div>
</template>

